
import streamlit as st
import pandas as pd
import base64
from io import BytesIO

LOGO_B64 = ""

def get_logo_html():
    return '<div style="text-align:center; margin-bottom:20px;"><img src="data:image/png;base64,' + LOGO_B64 + '" style="max-width:220px;"></div>'

st.set_page_config(page_title="Volontariato Varese - Registro", page_icon="🤝", layout="centered")

st.markdown(get_logo_html(), unsafe_allow_html=True)

st.markdown('''
<h1 style='text-align:center; color:#0e7a3d;'>VOLONTARIATO<br>SEZIONE DI VARESE</h1>
<h3 style='text-align:center;'>Registro Iscrizioni</h3>
''', unsafe_allow_html=True)

if "dati" not in st.session_state:
    st.session_state.dati = []

with st.form("form"):
    nome = st.text_input("Nome e Cognome *")
    assoc = st.text_input("Associazione *")
    cell = st.text_input("Cellulare *")
    ruolo = st.selectbox("Ruolo *", ["Volontario", "Caposquadra", "Coordinatore", "Autista", "Radio / Comunicazioni", "Logistica", "Segreteria", "Sanitario", "Altro"])
    submitted = st.form_submit_button("Salva e Aggiungi alla Lista", use_container_width=True)

    if submitted:
        if nome and assoc and cell:
            st.session_state.dati.append({"Nome e Cognome": nome, "Associazione": assoc, "Cellulare": cell, "Ruolo": ruolo})
            st.success(f"Aggiunto {nome} - {ruolo}")
        else:
            st.error("Compila tutti i campi con *")

if st.session_state.dati:
    df = pd.DataFrame(st.session_state.dati)
    st.divider()
    st.dataframe(df, use_container_width=True, hide_index=True)
    
    output = BytesIO()
    df.to_excel(output, index=False, engine='openpyxl')
    st.download_button("Scarica Excel (associazioni.xlsx)", output.getvalue(), file_name="associazioni.xlsx", mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", use_container_width=True)
    
    if st.button("Svuota Lista", use_container_width=True):
        st.session_state.dati = []
        st.rerun()
else:
    st.info("Nessun iscritto ancora. Compila il form sopra.")

st.markdown("<p style='text-align:center; font-size:12px; color:gray;'>Volontariato Sezione di Varese - Sistema con Ruolo</p>", unsafe_allow_html=True)
